import React, { useState, useEffect } from 'react';

const Autocomplete = ({ suggestions, onChange, value }) => {
  const [inputValue, setInputValue] = useState('');
  const [selectedSuggestion, setSelectedSuggestion] = useState(null);

  useEffect(() => {
    setInputValue(value);
  }, [value]);

  const handleInputChange = (event) => {
    const newValue = event.target.value;
    setInputValue(newValue);
    setSelectedSuggestion(null);
  };

  const handleSuggestionSelect = (suggestion) => {
    onChange(suggestion);
    setSelectedSuggestion(null);
  };

  const handleSuggestionKeyDown = (event) => {
    if (event.key === 'ArrowDown') {
      const currentSuggestion = suggestions.find((s) => s.toLowerCase().startsWith(inputValue.toLowerCase()));
      if (currentSuggestion) {
        setSelectedSuggestion(currentSuggestion);
      }
    } else if (event.key === 'ArrowUp') {
      const currentSuggestion = suggestions.filter((s) => s.toLowerCase().startsWith(inputValue.toLowerCase()));
      if (currentSuggestion.length > 1) {
        const index = suggestions.indexOf(selectedSuggestion);
        const prevSuggestion = currentSuggestion[index - 1] || currentSuggestion[currentSuggestion.length - 1];
        setSelectedSuggestion(prevSuggestion);
      }
    }
  };

  const getSuggestions = () => {
    const filteredSuggestions = suggestions.filter((s) => s.toLowerCase().startsWith(inputValue.toLowerCase()));
    if (selectedSuggestion) {
      return [selectedSuggestion].concat(filteredSuggestions);
    }
    return filteredSuggestions;
  };

  return (
    <div>
      <input
        type="text"
        value={inputValue}
        onChange={handleInputChange}
        onKeyDown={handleSuggestionKeyDown}
        placeholder="Type to search..."
      />
      {inputValue.length > 0 && (
        <ul>
          {getSuggestions().map((suggestion) => (
            <li onClick={() => handleSuggestionSelect(suggestion)} key={suggestion}>
              {suggestion}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Autocomplete;
```
